/**
 * Diagnosis for §3.1 (not a gate): which packages/sources make up a route's first-load JS. Needs a build with browser
 * source maps (`ANALYZE_MAPS=1 pnpm build`). Attributes each chunk's generated bytes (minified, pre-gzip) to the source
 * that produced them by decoding the source map, then groups by npm package or workspace directory.
 *
 *   pnpm --filter @cwf/scripts exec tsx perf/attribute.ts / /markets
 */
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { routeChunks } from "./route-budgets";

const root = join(import.meta.dirname, "..", "..", "web", ".next");
const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
const DEC = new Map([...B64].map((c, i) => [c, i]));

function vlq(segment: string): number[] {
  const out: number[] = [];
  let value = 0, shift = 0;
  for (const ch of segment) {
    const d = DEC.get(ch)!;
    value += (d & 31) << shift;
    if (d & 32) shift += 5;
    else {
      out.push(value & 1 ? -(value >>> 1) : value >>> 1);
      value = 0;
      shift = 0;
    }
  }
  return out;
}

type Map1 = { sources: string[]; mappings: string; sections?: { offset: { line: number; column: number }; map: Map1 }[] };

/** Adds bytes per source for one (possibly sectioned) map over the generated lines. */
function attribute(map: Map1, lines: string[], lineOffset: number, colOffset: number, into: Map<string, number>) {
  if (map.sections) {
    for (const s of map.sections) attribute(s.map, lines, lineOffset + s.offset.line, s.offset.column, into);
    return;
  }
  let src = 0;
  map.mappings.split(";").forEach((line, li) => {
    const text = lines[lineOffset + li] ?? "";
    let col = 0;
    const segs = line ? line.split(",").map(vlq) : [];
    const starts: { col: number; src: number | null }[] = [];
    for (const s of segs) {
      col += s[0]!;
      if (s.length >= 4) src += s[1]!;
      starts.push({ col: col + (li === 0 ? colOffset : 0), src: s.length >= 4 ? src : null });
    }
    starts.forEach((st, i) => {
      const end = starts[i + 1]?.col ?? text.length;
      if (st.src === null) return;
      const name = map.sources[st.src] ?? "?";
      into.set(name, (into.get(name) ?? 0) + Math.max(0, end - st.col));
    });
  });
}

function group(source: string): string {
  const s = source.replace(/^turbopack:\/\/\/?(\[project\]\/)?/, "");
  const nm = s.lastIndexOf("node_modules/");
  if (nm >= 0) {
    const rest = s.slice(nm + 13).split("/");
    const pkg = rest[0]!.startsWith("@") ? `${rest[0]}/${rest[1]}` : rest[0]!;
    // Deep mode (`--deep`): one level into the package (e.g. @base-ui/react/menu) to see which parts ship.
    return process.argv.includes("--deep") ? `${pkg}/${rest[pkg.startsWith("@") ? 3 : 2] ?? ""}` : pkg;
  }
  const parts = s.split("/");
  return parts.slice(0, parts[0] === "web" ? 4 : 3).join("/");
}

for (const route of process.argv.slice(2).filter((a) => !a.startsWith("--"))) {
  const bytes = new Map<string, number>();
  let total = 0;
  for (const chunk of routeChunks(route)) {
    const file = join(root, chunk);
    const code = readFileSync(file, "utf8");
    total += code.length;
    // Turbopack names the map in the chunk's `sourceMappingURL` comment (not `<chunk>.map`).
    const ref = /\/\/# sourceMappingURL=(\S+)\s*$/.exec(code)?.[1];
    const mapFile = ref ? join(file, "..", ref) : `${file}.map`;
    if (!existsSync(mapFile)) {
      bytes.set(`(no map) ${chunk}`, code.length);
      continue;
    }
    const perSource = new Map<string, number>();
    attribute(JSON.parse(readFileSync(mapFile, "utf8")) as Map1, code.split("\n"), 0, 0, perSource);
    for (const [src, n] of perSource) bytes.set(group(src), (bytes.get(group(src)) ?? 0) + n);
  }
  console.log(`\n${route} — ${(total / 1024).toFixed(0)} KB minified`);
  for (const [g, n] of [...bytes].sort((a, b) => b[1] - a[1]).slice(0, 28)) console.log(`${(n / 1024).toFixed(1).padStart(8)} KB  ${g}`);
}
